        "objectName": "作为一名敏捷项目经理，我希望新增一个&amp;quot;敏捷人员信息历史表&amp;quot;，用于记录和查询人员的敏捷小组变动信息，这样可以更好地进行团队管理、人员调配以及项目追踪。   file-read-2792899.png  验收标准：  1. 表结构设计共6个字段：id、工号、所属敏捷小组、所属团队、动作、操作时间。  2. 支持记录人员加入、离开的动作类型和时间信息，可追溯人员完整的团队变动历史。  3. 当发生敏捷小组解散时，组内全部人员触发退出动作，并记录相应信息。",
